// HEXA Matrix tracker. Board layout, skill names, Final Damage weights and the
// Sol Erda cost tables all live in hexa_data.js (generated by tools/gen_hexa_data.js).
//
// Saved shape, per tracking id (a classId for the standalone tab, 'char:<id>' for
// a roster character):
//   { classId?, levels: {skillKey: 0..30}, targets: {skillKey: 0..30}, excluded: {skillKey: bool} }
// `levels` is where you are now, `targets` is where you want to end up. Keys match
// the ones written by earlier versions, so existing saves carry over untouched.

const hexaTracker = {
    STORAGE_KEY: 'mapleManager_hexa_v1',
    MAX_LEVEL: 30,
    ICON_BASE: 'assets/hexa_icons/gms/',

    SKILL_TYPE_CONFIG: {
        mastery: { label: 'M', badge: '#f97316', color: '#fdba74', title: 'Mastery' },
        origin:  { label: 'O', badge: '#facc15', color: '#fde68a', title: 'Origin' },
        ascent:  { label: 'A', badge: '#eab308', color: '#fde047', title: 'Ascent' },
        enhance: { label: 'B', badge: '#38bdf8', color: '#7dd3fc', title: 'Boost' },
        common:  { label: 'C', badge: '#a78bfa', color: '#c4b5fd', title: 'Common' },
    },

    // Board tiers, in the order GMS shows them.
    TIERS: [
        { id: 'skillNodes', label: 'Skill Node', color: '#fde68a' },
        { id: 'mastery',    label: 'Mastery',    color: '#fdba74' },
        { id: 'boost',      label: 'Boost',      color: '#7dd3fc' },
        { id: 'common',     label: 'Common',     color: '#c4b5fd' },
    ],

    GROUP_LABELS: {
        EXPLORER: 'Explorer', CYGNUSKIGHT: 'Cygnus Knights',
        HERO: 'Heroes', RESISTANCE: 'Resistance', DEMON: 'Demon',
        NOVA: 'Nova', FLORA: 'Flora', ANIMA: 'Anima',
        FRIENDSWORLD: 'Friendship World', TRANSCENDENT: 'Transcendent',
        SENGOKU: 'Sengoku', JIANGHU: 'Jianghu', SHINE: 'Shine',
    },

    page: 'ranking',        // 'ranking' | 'tracker'
    prioritySort: 'frag',   // 'frag' | 'erda'
    planCap: 'target',      // 'target' | 'max' — where the 効率順 chain stops
    mapView: 'list',        // 'list' | 'tiles' | 'timeline' — how 強化順マップ draws the chain
    mapCursor: 0,           // timeline position, in levels taken from where you are now
    data: {},
    _loaded: false,

    init() {
        this.loadData();
        this.syncPageNav();
        this.render();
    },

    loadData() {
        try {
            const s = localStorage.getItem(this.STORAGE_KEY);
            if (s) this.data = JSON.parse(s);
        } catch (e) { this.data = {}; }
        this._loaded = true;
    },

    // The character modal can be opened (from the roster) before the HEXA view
    // runs init(); make sure saved data is loaded so we never overwrite it.
    ensureLoaded() {
        if (!this._loaded) this.loadData();
    },

    saveData() {
        try { localStorage.setItem(this.STORAGE_KEY, JSON.stringify(this.data)); } catch (e) {}
    },

    getClassSkills(id) {
        return (window.HEXA_CLASS_SKILLS || []).find(c => c.id === id);
    },

    getClassInfo(id) {
        for (const group of Object.values(window.CLASS_DATA || {})) {
            const f = group.find(c => c.id === id);
            if (f) return f;
        }
        return null;
    },

    getSkillIcon(skill) {
        return skill && skill.icon ? this.ICON_BASE + skill.icon + '.png' : null;
    },

    // ========== Cost model ==========

    // Which HEXA_COST table a node pays from. Origin has its own table because
    // its Lv.1 is granted free when you hit 6th job; the 3rd Common core is
    // cheaper than the first two.
    costKey(skill) {
        if (skill.type === 'origin') return 'origin';
        if (skill.type === 'ascent') return 'ascent';
        if (skill.type === 'mastery') return 'mastery';
        if (skill.type === 'enhance') return 'enhance';
        if (skill.type === 'common') return skill.slot === 2 ? 'common3' : 'common';
        return 'mastery';
    },

    // Lowest level a node can sit at (Origin is auto-granted at Lv.1).
    minLevel(skill) {
        return (window.HEXA_MIN_LEVEL || {})[skill.type] || 0;
    },

    clampLevel(skill, v) {
        const n = parseInt(v, 10);
        return Math.max(this.minLevel(skill), Math.min(this.MAX_LEVEL, isNaN(n) ? 0 : n));
    },

    table(skill) {
        return (window.HEXA_COST || {})[this.costKey(skill)] || (window.HEXA_COST || {}).mastery;
    },

    // Cumulative Sol Erda Fragments spent to sit at `level`.
    fragAt(skill, level) {
        const t = this.table(skill);
        if (!t) return 0;
        return t.frag[Math.max(0, Math.min(this.MAX_LEVEL, level))] || 0;
    },

    // Cumulative Sol Erda spent to sit at `level`.
    erdaAt(skill, level) {
        const t = this.table(skill);
        if (!t) return 0;
        return t.erda[Math.max(0, Math.min(this.MAX_LEVEL, level))] || 0;
    },

    // ========== Final Damage model ==========

    // Share of a node's FD weight unlocked at `level`. Nodes that ship an explicit
    // curve use it; the rest follow the per-tier shape in HEXA_FD_FALLBACK.
    fdAt(skill, level) {
        const n = Math.max(0, Math.min(this.MAX_LEVEL, level));
        if (n <= 0 || !skill.fd) return 0;

        const curves = window.HEXA_FD_CURVES || [];
        if (skill.c >= 0 && curves[skill.c]) {
            const curve = curves[skill.c];
            let total = 0, acc = 0;
            for (let i = 0; i < curve.length; i++) {
                total += curve[i];
                if (i < n) acc += curve[i];
            }
            return total > 0 ? acc / total * skill.fd : 0;
        }

        const f = (window.HEXA_FD_FALLBACK || {})[skill.tier];
        if (!f) return 0;
        let share = f.first;
        share += f.first > 0 ? (n - 1) / 29 * f.slope : n / 30 * f.slope;
        if (n >= 10) share += f.steps[10];
        if (n >= 20) share += f.steps[20];
        if (n >= 30) share += f.steps[30];
        return share * skill.fd;
    },

    // ========== Saved state ==========

    entry(trackingId) {
        return this.data[trackingId] || {};
    },

    // Current level of a node, floored at its auto-granted minimum.
    levelOf(trackingId, skill) {
        const levels = this.entry(trackingId).levels || {};
        return Math.max(this.minLevel(skill), levels[skill.key] || 0);
    },

    // Target level of a node. Unset means "take it to 30".
    targetOf(trackingId, skill) {
        const targets = this.entry(trackingId).targets || {};
        const t = targets[skill.key];
        const v = (typeof t === 'number') ? t : this.MAX_LEVEL;
        return Math.max(this.levelOf(trackingId, skill), Math.min(this.MAX_LEVEL, v));
    },

    isExcluded(trackingId, skill) {
        return !!(this.entry(trackingId).excluded || {})[skill.key];
    },

    // Nodes that count toward progress: released, and not manually excluded.
    activeSkills(trackingId, classId) {
        const cls = this.getClassSkills(classId);
        if (!cls) return [];
        return cls.skills.filter(s => !this.isExcluded(trackingId, s));
    },

    // Sol Janus carries no Final Damage — it is a buff-action node — and neither
    // do a handful of utility nodes the source weights at zero. Counting their
    // cost would drag down every rate on the board and inflate every "to max"
    // figure, so damage math leaves them out entirely. They stay on the board so
    // you can still record their level.
    countsForDamage(skill) {
        return skill.fd > 0;
    },

    // Every aggregate on every tab is built from these.
    damageSkills(trackingId, classId) {
        return this.activeSkills(trackingId, classId).filter(s => this.countsForDamage(s));
    },

    // The ones left out, for the note under the board.
    nonDamageSkills(classId) {
        const cls = this.getClassSkills(classId);
        if (!cls) return [];
        return cls.skills.filter(s => !this.countsForDamage(s) && s.name !== 'TBD');
    },

    // trackingId selects which saved data set to use; classId selects the board.
    getProgress(trackingId, classId) {
        this.ensureLoaded();
        if (classId === undefined) classId = trackingId;
        const empty = {
            pct: 0, pctToTarget: 0,
            fragSpent: 0, fragMax: 0, fragTarget: 0,
            erdaSpent: 0, erdaMax: 0, erdaTarget: 0,
            fdNow: 0, fdMax: 0, fdTarget: 0,
        };
        if (!this.getClassSkills(classId)) return empty;

        const out = { ...empty };
        for (const s of this.damageSkills(trackingId, classId)) {
            const lv = this.levelOf(trackingId, s);
            const tg = this.targetOf(trackingId, s);
            out.fragSpent += this.fragAt(s, lv);
            out.fragTarget += this.fragAt(s, tg);
            out.fragMax += this.fragAt(s, this.MAX_LEVEL);
            out.erdaSpent += this.erdaAt(s, lv);
            out.erdaTarget += this.erdaAt(s, tg);
            out.erdaMax += this.erdaAt(s, this.MAX_LEVEL);

            out.fdNow += this.fdAt(s, lv);
            out.fdTarget += this.fdAt(s, tg);
            out.fdMax += this.fdAt(s, this.MAX_LEVEL);
        }
        out.pct = out.fragMax > 0 ? Math.round(out.fragSpent / out.fragMax * 100) : 0;
        out.pctToTarget = out.fragTarget > 0 ? Math.round(out.fragSpent / out.fragTarget * 100) : 0;
        return out;
    },

    // HEXA Final Damage stacks additively into one bucket, so going from +a% to
    // +b% multiplies your damage by (100+b)/(100+a) — not by (b-a)%. The board
    // is quoted in additive points; this is what those points are actually worth.
    damageGain(fromFd, toFd) {
        return ((100 + toFd) / (100 + fromFd) - 1) * 100;
    },

    // ========== Priority: what to level next, by FD per resource ==========

    setPrioritySort(kind) {
        this.prioritySort = kind;
        this.refreshAll();
    },

    setPlanCap(cap) {
        this.planCap = cap;
        this.refreshAll();
    },

    setMapView(view) {
        this.mapView = view;
        this.refreshAll();
    },

    // Greedy chain from current levels to targets: repeatedly take the single
    // level with the best FD per resource, then merge consecutive levels of the
    // same node into one step (their ratios are equal, so the order is unchanged).
    // One greedy level at a time, from `from` to `to`. Because each pick is the
    // best remaining ratio and the nodes are independent, the ratios come out
    // non-increasing — which is what makes the cumulative curve concave and the
    // break-even point below well defined.
    planSingles(skills, from, to, perErda) {
        const cursor = { ...from };
        const singles = [];
        // Bounded by every node's remaining levels, so this always terminates.
        const cap = skills.length * this.MAX_LEVEL;
        for (let guard = 0; guard < cap; guard++) {
            let best = null;
            for (const s of skills) {
                const lv = cursor[s.key];
                if (lv >= to[s.key]) continue;
                const frag = this.fragAt(s, lv + 1) - this.fragAt(s, lv);
                const erda = this.erdaAt(s, lv + 1) - this.erdaAt(s, lv);
                const fd = this.fdAt(s, lv + 1) - this.fdAt(s, lv);
                const cost = perErda ? erda : frag;
                const ratio = cost > 0 ? fd / cost : (fd > 0 ? Infinity : 0);
                if (!best || ratio > best.ratio) best = { skill: s, from: lv, frag, erda, fd, ratio };
            }
            if (!best) break;
            cursor[best.skill.key] = best.from + 1;
            singles.push(best);
        }
        return singles;
    },

    // Collapse a run of consecutive levels on one node into a single step.
    mergeSteps(singles) {
        const steps = [];
        for (const step of singles) {
            const last = steps[steps.length - 1];
            if (last && last.skill.key === step.skill.key && last.to === step.from) {
                last.to = step.from + 1;
                last.frag += step.frag;
                last.erda += step.erda;
                last.fd += step.fd;
                continue;
            }
            steps.push({ skill: step.skill, from: step.from, to: step.from + 1, frag: step.frag, erda: step.erda, fd: step.fd, ratio: step.ratio });
        }
        return steps;
    },

    // Nodes that can move the needle, with their level bounds.
    planScope(trackingId, classId) {
        const skills = this.damageSkills(trackingId, classId);
        const floor = {}, current = {}, target = {}, max = {};
        for (const s of skills) {
            floor[s.key] = this.minLevel(s);
            current[s.key] = this.levelOf(trackingId, s);
            target[s.key] = this.targetOf(trackingId, s);
            max[s.key] = this.MAX_LEVEL;
        }
        return { skills, floor, current, target, max };
    },

    // The chain from where you are now to your targets (or to Lv.30 everywhere,
    // when planCap is 'max'), merged for display.
    buildPlan(trackingId, classId) {
        const { skills, current, target, max } = this.planScope(trackingId, classId);
        const upTo = this.planCap === 'max' ? max : target;
        return this.mergeSteps(this.planSingles(skills, current, upTo, this.prioritySort === 'erda'));
    },

    // ========== Efficiency curve ==========

    // The best jump available from `lv` on one node, measured in Final Damage per
    // fragment. This looks past the next level rather than only at it, which
    // matters because levels 10, 20 and 30 cost several times their neighbours:
    // taking 9→10 alone is a terrible rate, but 9→12 as a block can still be the
    // best move on the board. Evaluating blocks is what makes the resulting curve
    // concave, and a concave curve is what makes a break-even point meaningful.
    bestBlock(skill, lv, top) {
        const fdL = this.fdAt(skill, lv), fragL = this.fragAt(skill, lv), erdaL = this.erdaAt(skill, lv);
        let best = null;
        for (let m = lv + 1; m <= top; m++) {
            const frag = this.fragAt(skill, m) - fragL;
            const fd = this.fdAt(skill, m) - fdL;
            const ratio = frag > 0 ? fd / frag : (fd > 0 ? Infinity : 0);
            if (!best || ratio > best.ratio) best = { to: m, frag, erda: this.erdaAt(skill, m) - erdaL, fd, ratio };
        }
        return best;
    },

    // The class's whole investment curve: an untouched board taken to Lv.30
    // everywhere, always spending on whatever block returns the most Final Damage
    // per fragment. It does not depend on where you are now, which is what makes
    // it a planning reference — your own position gets plotted on top of it.
    //
    // Note this is deliberately not the same ordering as the 効率順 tab. That tab
    // answers "what do I buy next", one level at a time; this one traces the best
    // rate achievable at each spend level, so it is allowed to commit to a block.
    curveData(trackingId, classId) {
        const skills = this.damageSkills(trackingId, classId);
        const cursor = {}, top = {};
        let fd = 0;
        for (const s of skills) {
            cursor[s.key] = this.minLevel(s);
            top[s.key] = this.MAX_LEVEL;
            fd += this.fdAt(s, cursor[s.key]);
        }

        const fdFloor = fd;
        const points = [{ frag: 0, erda: 0, fd, ratio: Infinity, skill: null, to: 0 }];
        let frag = 0, erda = 0;
        // Bounded: every iteration advances one node's level by at least one.
        const cap = skills.length * this.MAX_LEVEL;
        for (let guard = 0; guard < cap; guard++) {
            let best = null;
            for (const s of skills) {
                const lv = cursor[s.key];
                if (lv >= top[s.key]) continue;
                const b = this.bestBlock(s, lv, top[s.key]);
                if (b && (!best || b.ratio > best.ratio)) best = { skill: s, from: lv, ...b };
            }
            if (!best) break;
            cursor[best.skill.key] = best.to;
            frag += best.frag; erda += best.erda; fd += best.fd;
            points.push({ frag, erda, fd, ratio: best.ratio, skill: best.skill, from: best.from, to: best.to });
        }

        // The slope to compare against: the whole board's Final Damage divided by
        // its whole fragment cost, i.e. the average rate of maxing everything.
        // Because the block rates only ever fall, there is exactly one crossing —
        // before it every purchase beats that average, after it none do.
        const avg = frag > 0 ? (fd - fdFloor) / frag : 0;
        let breakIdx = points.length - 1;
        for (let i = 1; i < points.length; i++) {
            if (points[i].ratio < avg) { breakIdx = i - 1; break; }
        }
        return { points, totalFrag: frag, totalErda: erda, fdMax: fd, fdFloor, avg, breakIdx };
    },

    // Where `fdWanted` sits on the curve. Inside a block the curve is a straight
    // line by construction, so interpolating there is exact rather than a guess.
    curveAt(curve, fdWanted) {
        const pts = curve.points;
        for (let i = 1; i < pts.length; i++) {
            if (pts[i].fd < fdWanted - 1e-9) continue;
            const a = pts[i - 1], b = pts[i];
            const span = b.fd - a.fd;
            const k = span > 1e-12 ? Math.max(0, Math.min(1, (fdWanted - a.fd) / span)) : 1;
            return {
                idx: i,
                p: {
                    fd: a.fd + (b.fd - a.fd) * k,
                    frag: a.frag + (b.frag - a.frag) * k,
                    erda: a.erda + (b.erda - a.erda) * k,
                    ratio: b.ratio,
                    skill: b.skill,
                    to: b.to,
                },
            };
        }
        return { p: pts[pts.length - 1], idx: pts.length - 1 };
    },

    // ========== Rendering ==========

    render() {
        const root = document.getElementById('view-hexa');
        if (!root) return;
        root.innerHTML = this.buildHTML();
        lucide.createIcons();
    },

    buildHTML() {
        return `<div class="flex flex-col h-[calc(100vh-8.5rem)]">
            <div class="flex-1 overflow-y-auto custom-scrollbar pr-1" id="hexa-page">
                ${this.buildPageBody()}
            </div>
        </div>`;
    },

    // The page switch lives in the app's top bar (#hexa-nav in index.html), next
    // to the other apps' sub-navs, rather than as a second tab row inside the view.
    setPage(page) {
        this.page = page;
        this.syncPageNav();
        this.render();
    },

    syncPageNav() {
        for (const id of ['ranking', 'tracker']) {
            const btn = document.getElementById('hnav-' + id);
            if (!btn) continue;
            const on = this.page === id;
            btn.classList.toggle('nav-active', on);
            btn.classList.toggle('nav-inactive', !on);
        }
    },

    buildPageBody() {
        return this.page === 'tracker' ? this.buildTrackerGrid() : this.buildRanking();
    },

    // ========== Ranking: fragments needed to reach a given share of max FD ==========

    // Progress milestones to rank by. `pct` is a share of the class's own maximum
    // Final Damage; the break-even point is where a level's rate falls to the
    // whole-board average, so it lands at a different share for every class.
    RANK_STEPS: [
        { key: '20', label: '20%' }, { key: '40', label: '40%' }, { key: '60', label: '60%' },
        { key: '80', label: '80%' }, { key: '85', label: '85%' }, { key: '90', label: '90%' },
        { key: '95', label: '95%' }, { key: 'break', label: '分岐点' },
    ],
    rankStep: 'break',

    setRankStep(key) {
        this.rankStep = key;
        const body = document.getElementById('hexa-page');
        if (body) body.innerHTML = this.buildPageBody();
        if (window.lucide) lucide.createIcons();
    },

    // Curves for the ranking ignore per-character exclusions, so every class is
    // measured on the same board. They never change, so compute each one once.
    rankCurve(classId) {
        if (!this._rankCurves) this._rankCurves = {};
        if (!(classId in this._rankCurves)) this._rankCurves[classId] = this.curveData(null, classId);
        return this._rankCurves[classId];
    },

    rankRows(stepKey) {
        const rows = [];
        for (const cls of (window.HEXA_CLASS_SKILLS || [])) {
            const info = this.getClassInfo(cls.id);
            if (!info) continue;
            const curve = this.rankCurve(cls.id);
            // Classes with no GMS node table yet (Erel Light) have nothing to rank.
            if (!curve || curve.totalFrag <= 0) continue;
            const p = stepKey === 'break'
                ? curve.points[curve.breakIdx]
                : this.curveAt(curve, curve.fdMax * Number(stepKey) / 100).p;
            rows.push({
                id: cls.id, name: info.name, path: info.path, group: this.getClassGroup(cls.id),
                frag: p.frag, erda: p.erda, fd: p.fd, fdMax: curve.fdMax,
                share: curve.fdMax > 0 ? p.fd / curve.fdMax * 100 : 0,
            });
        }
        rows.sort((a, b) => a.frag - b.frag);
        return rows;
    },

    getClassGroup(classId) {
        for (const [groupId, classes] of Object.entries(window.CLASS_DATA || {})) {
            if (classes.some(c => c.id === classId)) return this.GROUP_LABELS[groupId] || groupId;
        }
        return '';
    },

    buildRanking() {
        const rows = this.rankRows(this.rankStep);
        if (!rows.length) return this.buildEmptyState();

        const maxFrag = rows[rows.length - 1].frag || 1;
        const isBreak = this.rankStep === 'break';

        const steps = this.RANK_STEPS.map(s => `<button onclick="hexaTracker.setRankStep('${s.key}')"
            class="px-3 py-1.5 text-xs font-bold rounded-md transition-colors ${this.rankStep === s.key ? 'bg-violet-600 text-white' : 'text-slate-400 hover:text-slate-200 hover:bg-slate-800'}">${s.label}</button>`).join('');

        let list = '';
        rows.forEach((r, i) => {
            const medal = i === 0 ? '#fcd34d' : i === 1 ? '#cbd5e1' : i === 2 ? '#d97706' : null;
            list += `<button onclick="hexaTracker.openForClass('${r.id}')"
                class="w-full flex items-center gap-3 px-2.5 py-0.5 text-left transition-colors hover:bg-slate-800/70 ${i % 2 ? 'bg-slate-950/50' : ''}">
                <span class="w-7 text-right text-xs font-bold tabular-nums shrink-0" style="color:${medal || '#64748b'}">${i + 1}</span>
                <img src="${r.path}" class="w-7 h-7 object-contain shrink-0" loading="lazy" alt="">
                <span class="w-56 shrink-0 min-w-0 flex items-baseline gap-2">
                    <span class="text-xs text-slate-200 truncate">${this.escHtml(r.name)}</span>
                    <span class="text-[10px] text-slate-500 truncate">${this.escHtml(r.group)}</span>
                </span>
                <span class="flex-1 min-w-0 hidden sm:block">
                    <span class="block h-1.5 bg-slate-800 overflow-hidden">
                        <span class="block h-full" style="width:${(r.frag / maxFrag * 100).toFixed(1)}%;background:linear-gradient(90deg,#7c3aed,#a78bfa)"></span>
                    </span>
                </span>
                <span class="w-24 text-right text-xs font-bold tabular-nums text-violet-300 shrink-0">${Math.round(r.frag).toLocaleString()}</span>
                <span class="w-16 text-right text-xs tabular-nums text-amber-300 shrink-0">${Math.round(r.erda).toLocaleString()}</span>
                <span class="w-20 text-right text-xs tabular-nums text-emerald-300 shrink-0" title="この地点の最終ダメージ（全取得時 +${r.fdMax.toFixed(1)}%）">+${r.fd.toFixed(1)}%</span>
                ${isBreak ? `<span class="w-12 text-right text-[10px] tabular-nums text-slate-500 shrink-0" title="全取得FDに対する到達率">${r.share.toFixed(0)}%</span>` : ''}
            </button>`;
        });

        const fastest = rows[0], slowest = rows[rows.length - 1];
        return `<div class="max-w-6xl">
            <div class="flex flex-wrap items-center justify-between gap-3 mb-2">
                <div>
                    <h2 class="text-lg font-bold text-white flex items-center gap-2 leading-tight">
                        <i data-lucide="trophy" class="w-4 h-4 text-amber-300"></i>HEXA効率ランキング
                    </h2>
                    <p class="text-[11px] text-slate-500 mt-0.5">
                        ${isBreak
                            ? 'コスパの分岐点（1レベルの効率が全体平均まで落ちる地点）に必要なソルエルダフラグメントが少ない順です。'
                            : `全取得時の最終ダメージの${this.rankStep}%に到達するまでに必要なソルエルダフラグメントが少ない順です。`}
                    </p>
                </div>
                <div class="inline-flex flex-wrap rounded-lg bg-slate-900 p-0.5 border border-slate-700">${steps}</div>
            </div>

            <div class="flex flex-wrap items-center gap-x-4 gap-y-1 text-[11px] text-slate-400 mb-2 px-1">
                <span>${rows.length}職</span>
                <span>最少 <span class="text-slate-200 font-bold">${this.escHtml(fastest.name)}</span>
                    <span class="text-violet-300 tabular-nums font-bold">${Math.round(fastest.frag).toLocaleString()}</span> 欠片</span>
                <span>最多 <span class="text-slate-200 font-bold">${this.escHtml(slowest.name)}</span>
                    <span class="text-violet-300 tabular-nums font-bold">${Math.round(slowest.frag).toLocaleString()}</span> 欠片</span>
                <span class="text-slate-600">差 ${Math.round(slowest.frag - fastest.frag).toLocaleString()} 欠片（${(slowest.frag / Math.max(1, fastest.frag)).toFixed(1)}倍）</span>
            </div>

            <div class="bg-slate-900 border border-slate-800 py-1">
                <div class="flex items-center gap-3 px-2.5 pb-1.5 mb-1 border-b border-slate-800 text-[9px] uppercase tracking-wider text-slate-500 font-bold">
                    <span class="w-7 text-right shrink-0">#</span>
                    <span class="w-7 shrink-0"></span>
                    <span class="w-56 shrink-0">職業</span>
                    <span class="flex-1 hidden sm:block"></span>
                    <span class="w-24 text-right shrink-0">必要欠片</span>
                    <span class="w-16 text-right shrink-0">エルダ</span>
                    <span class="w-20 text-right shrink-0">到達FD</span>
                    ${isBreak ? '<span class="w-12 text-right shrink-0">到達率</span>' : ''}
                </div>
                ${list}
            </div>
            <p class="text-[10px] text-slate-600 mt-3 leading-relaxed">
                未強化の盤面から、「最終ダメージ / 欠片」が最大の順に振った場合の必要量です。
                行をクリックすると、その職業のトラッカーが開きます。
                消費リソースは正確な値、最終ダメージはノード係数からの推定値です。
            </p>
        </div>`;
    },

    // ========== Tracker: one card per class, grouped like the roster ==========

    buildTrackerGrid() {
        if (!window.CLASS_DATA) return '';
        let html = '';
        for (const [groupId, classes] of Object.entries(CLASS_DATA)) {
            const hexaClasses = classes.filter(c => this.getClassSkills(c.id));
            if (!hexaClasses.length) continue;
            const label = this.GROUP_LABELS[groupId] || groupId;

            let cards = '';
            for (const cls of hexaClasses) {
                const p = this.getProgress(cls.id, cls.id);
                const started = p.fragSpent > 0;
                cards += `<button onclick="hexaTracker.openForClass('${cls.id}')"
                    class="flex items-center gap-2 px-1.5 py-1 rounded-none border text-left transition-colors ${started ? 'bg-slate-900 border-violet-800/60 hover:border-violet-500' : 'bg-slate-900/60 border-slate-800 hover:border-slate-600'}">
                    <img src="${cls.path}" class="w-9 h-9 object-contain shrink-0" loading="lazy" alt="">
                    <div class="flex-1 min-w-0">
                        <div class="text-[13px] font-bold text-slate-100 truncate">${this.escHtml(cls.name)}</div>
                        ${started
                            ? `<div class="text-[10px] text-emerald-300 tabular-nums">+${p.fdNow.toFixed(1)}% <span class="text-slate-600">/ +${p.fdMax.toFixed(1)}%</span></div>
                               <div class="h-1 bg-slate-800 rounded-full overflow-hidden mt-1">
                                   <div class="h-full rounded-full" style="width:${p.pct}%;background:linear-gradient(90deg,#7c3aed,#8b5cf6)"></div>
                               </div>`
                            : `<div class="text-[10px] text-slate-600">未入力</div>`}
                    </div>
                    ${started ? `<span class="text-[11px] font-bold tabular-nums text-violet-300 shrink-0">${p.pct}%</span>` : ''}
                </button>`;
            }

            html += `<div class="mb-3">
                <div class="flex items-baseline gap-2 px-1 mb-1">
                    <span class="text-[10px] font-bold uppercase tracking-widest text-slate-400">${this.escHtml(label)}</span>
                    <span class="text-[10px] text-slate-600">${hexaClasses.length}職</span>
                </div>
                <div class="grid grid-cols-2 lg:grid-cols-4 xl:grid-cols-6 gap-1">${cards}</div>
            </div>`;
        }
        return `<div>
            <div class="flex items-baseline gap-3 mb-2">
                <h2 class="text-lg font-bold text-white leading-tight">HEXAトラッカー</h2>
                <p class="text-[11px] text-slate-500">職業カードをクリックすると、進捗入力・効率順・効率カーブを開けます。</p>
            </div>
            ${html}
        </div>`;
    },

    buildEmptyState() {
        return `<div class="flex items-center justify-center h-full">
            <div class="text-center text-slate-500">
                <i data-lucide="hexagon" class="w-14 h-14 mx-auto mb-4 opacity-20"></i>
                <p class="text-sm font-medium">表示できる職業データがありません</p>
            </div>
        </div>`;
    },

    // Tab strip inside the modal.
    buildTabs() {
        // Same look as the app's top-bar tabs (.htab), since this row is the
        // popup's own header.
        const tab = (id, label, icon) => `<button onclick="hexaTracker.setTab('${id}')"
            class="htab ${this.modalTab === id ? 'nav-active' : 'nav-inactive'}">
            <i data-lucide="${icon}" class="w-3.5 h-3.5"></i>${label}
        </button>`;
        return tab('progress', '進捗入力', 'sliders-horizontal')
            + tab('map', '強化順マップ', 'layout-grid')
            + tab('curve', '効率カーブ', 'activity');
    },

    setTab(tab) {
        this.modalTab = tab;
        this.refreshAll();
    },

    buildSkillPanel(classId, trackingId) {
        if (trackingId === undefined) trackingId = classId;
        const cls = this.getClassSkills(classId);
        const info = this.getClassInfo(classId);
        if (!cls || !info) return this.buildEmptyState();

        const p = this.getProgress(trackingId, classId);

        let groups = '';
        for (const tier of this.TIERS) {
            groups += this.buildSkillGroup(tier, cls, trackingId, classId);
        }

        return `<div>
            ${this.buildResourceSummary(p)}
            <div class="grid grid-cols-2 gap-2.5">${groups}</div>
            ${this.buildExclusionNote(classId)}
        </div>`;
    },

    // Say plainly which nodes are kept out of the numbers, so a total that looks
    // short has a visible reason.
    buildExclusionNote(classId) {
        const sentence = this.exclusionSentence(classId);
        if (!sentence) return '';
        return `<p class="text-[10px] text-slate-600 mt-2 leading-relaxed flex items-start gap-1.5">
            <i data-lucide="info" class="w-3 h-3 shrink-0 mt-0.5"></i>
            <span>${sentence}</span>
        </p>`;
    },

    // Same sentence, for tabs that already have a footnote to append it to.
    exclusionSentence(classId) {
        const left = this.nonDamageSkills(classId);
        if (!left.length) return '';
        const names = [...new Set(left.map(s => s.name))].join('、');
        return `${this.escHtml(names)} は最終ダメージに寄与しないため、フラグメント・エルダ・FDのすべての集計から除外しています（レベルの記録のみ可）。`;
    },

    // Secondary: the three running totals, each as its own 現在 / 目標 / 最大 stack
    // so the rows line up and the numbers stay comparable down the column.
    buildResourceSummary(p) {
        const pctColor = p.pct >= 80 ? '#4ade80' : p.pct >= 50 ? '#a78bfa' : '#818cf8';
        const targetPct = p.fragMax > 0 ? p.fragTarget / p.fragMax * 100 : 0;
        const remFrag = Math.max(0, p.fragTarget - p.fragSpent);
        const remErda = Math.max(0, p.erdaTarget - p.erdaSpent);
        const remFd = Math.max(0, p.fdTarget - p.fdNow);

        const column = (title, dot, color, rows, remaining) => `<div class="flex-1 min-w-[150px] px-3">
            <div class="flex items-center gap-1.5 text-[10px] font-bold uppercase tracking-wider leading-4" style="color:${color}">
                <span class="inline-block w-2 h-2 rounded-full" style="background:${dot}"></span>${title}
            </div>
            <dl>
                ${rows.map(([label, value, strong]) => `<div class="flex items-baseline justify-between gap-2 leading-tight">
                    <dt class="text-[10px] text-slate-500 shrink-0">${label}</dt>
                    <dd class="text-[12px] tabular-nums ${strong ? 'font-bold text-slate-100' : 'text-slate-400'}">${value}</dd>
                </div>`).join('')}
                <div class="flex items-baseline justify-between gap-2 leading-tight mt-0.5 pt-0.5 border-t border-slate-800">
                    <dt class="text-[10px] text-slate-500 shrink-0">目標まで残り</dt>
                    <dd class="text-[11px] font-bold tabular-nums" style="color:${color}">${remaining}</dd>
                </div>
            </dl>
        </div>`;

        return `<div class="bg-slate-900 rounded-xl border border-slate-800 p-2 mb-2">
            <div class="flex items-center gap-3 mb-1.5">
                <div class="relative flex-1 h-1.5 bg-slate-800 rounded-full overflow-hidden">
                    <div class="absolute inset-y-0 left-0 rounded-full bg-violet-500/25" style="width:${targetPct}%"></div>
                    <div class="absolute inset-y-0 left-0 rounded-full transition-all duration-500"
                        style="width:${p.pct}%; background:linear-gradient(90deg,#7c3aed,#8b5cf6)"></div>
                </div>
                <span class="text-xs font-bold w-10 text-right tabular-nums leading-none" style="color:${pctColor}" title="投入済みフラグメント / 全取得に必要なフラグメント">${p.pct}%</span>
            </div>
            <div class="flex flex-wrap items-stretch divide-x divide-slate-800">
                ${column('フラグメント', '#a78bfa', '#c4b5fd', [
                    ['現在', p.fragSpent.toLocaleString(), true],
                    ['目標', p.fragTarget.toLocaleString(), false],
                    ['最大', p.fragMax.toLocaleString(), false],
                ], remFrag.toLocaleString())}
                ${column('ソルエルダ', '#fcd34d', '#fcd34d', [
                    ['現在', p.erdaSpent.toLocaleString(), true],
                    ['目標', p.erdaTarget.toLocaleString(), false],
                    ['最大', p.erdaMax.toLocaleString(), false],
                ], remErda.toLocaleString())}
                ${column('最終ダメージ', '#34d399', '#34d399', [
                    ['現在', `+${p.fdNow.toFixed(1)}%`, true],
                    ['目標', `+${p.fdTarget.toFixed(1)}%`, false],
                    ['最大', `+${p.fdMax.toFixed(1)}%`, false],
                ], `+${remFd.toFixed(1)}%`)}
            </div>
        </div>`;
    },

    buildSkillGroup(tier, cls, trackingId, classId) {
        const skills = cls.skills.filter(s => s.tier === tier.id);
        const slots = (cls.slots || {})[tier.id] || skills.length;
        if (!skills.length && slots <= 0) return '';

        let rows = '';
        for (const s of skills) {
            const sCfg = this.SKILL_TYPE_CONFIG[s.type] || this.SKILL_TYPE_CONFIG.mastery;
            const lvl = this.levelOf(trackingId, s);
            const tgt = this.targetOf(trackingId, s);
            const isExcl = this.isExcluded(trackingId, s);
            const fragNow = this.fragAt(s, lvl);
            const fragTgt = this.fragAt(s, tgt);
            const fragMax = this.fragAt(s, this.MAX_LEVEL);
            const pct = fragMax > 0 ? Math.round(fragNow / fragMax * 100) : 0;
            const tgtPct = fragMax > 0 ? Math.round(fragTgt / fragMax * 100) : 0;
            const iconUrl = this.getSkillIcon(s);
            const iconHtml = iconUrl
                ? `<img src="${iconUrl}" class="w-6 h-6 object-contain shrink-0 rounded" loading="lazy" alt="">`
                : `<div class="w-6 h-6 rounded-full flex items-center justify-center text-[10px] font-bold text-white shrink-0" style="background:${sCfg.badge}">${sCfg.label}</div>`;

            const counts = this.countsForDamage(s);
            const fdNow = this.fdAt(s, lvl);
            const hint = counts
                ? `${s.name}\n最終ダメージ 現在 +${fdNow.toFixed(2)}% / 全取得 +${s.fd.toFixed(2)}%`
                    + `\nフラグメント ${fragNow.toLocaleString()} / 全取得 ${fragMax.toLocaleString()}`
                : `${s.name}\n最終ダメージに寄与しないため、画面上のすべての集計から除外しています。`
                    + `\nレベルの記録だけできます（フラグメント ${fragNow.toLocaleString()}）。`;
            const stat = isExcl ? '除外'
                : !counts ? '<span class="text-slate-500">火力計算外</span>'
                : `<span class="text-emerald-400">+${fdNow.toFixed(1)}%</span><span class="text-slate-700 mx-1">·</span><span class="text-slate-500">${fragNow.toLocaleString()}</span>`;

            rows += `<div class="flex items-center gap-2 py-1 border-b border-slate-800/50 last:border-0 ${isExcl ? 'opacity-40' : counts ? '' : 'opacity-60'}">
                ${iconHtml}
                <div class="flex-1 min-w-0">
                    <div class="flex items-baseline justify-between gap-1.5 leading-4">
                        <div class="text-[11px] text-slate-300 leading-snug truncate" title="${this.escHtml(hint)}">${this.escHtml(s.name)}</div>
                        <div class="text-[9px] shrink-0 tabular-nums" title="${this.escHtml(hint)}">${stat}</div>
                    </div>
                    <div class="relative h-1 bg-slate-700/60 rounded-full mt-0.5 overflow-hidden">
                        <div class="absolute inset-y-0 left-0 rounded-full opacity-40" style="width:${isExcl ? 0 : tgtPct}%;background:${sCfg.badge}"></div>
                        <div class="absolute inset-y-0 left-0 rounded-full transition-all" style="width:${isExcl ? 0 : pct}%;background:${sCfg.badge}"></div>
                    </div>
                </div>
                <select title="現在地"
                    onchange="hexaTracker.updateLevel('${trackingId}','${classId}','${s.key}',this.value)"
                    class="w-12 bg-slate-800 border border-slate-700 rounded text-xs text-white py-0.5 pl-1 cursor-pointer focus:outline-none focus:border-violet-500 shrink-0">
                    ${this.levelOptions(this.minLevel(s), lvl)}
                </select>
                <span class="text-[10px] text-slate-600 shrink-0">→</span>
                <select title="目標値"
                    onchange="hexaTracker.updateTarget('${trackingId}','${classId}','${s.key}',this.value)"
                    class="w-12 bg-slate-950 border border-violet-800/70 rounded text-xs text-violet-200 py-0.5 pl-1 cursor-pointer focus:outline-none focus:border-violet-500 shrink-0">
                    ${this.levelOptions(lvl, tgt)}
                </select>
                ${counts ? `<button onclick="hexaTracker.toggleExclude('${trackingId}','${s.key}')"
                    title="${isExcl ? '進捗に含める' : '進捗から除外'}"
                    class="w-5 h-5 rounded border flex items-center justify-center shrink-0 transition-colors ${isExcl ? 'bg-slate-700 border-slate-600' : 'border-slate-600 hover:border-slate-400 hover:bg-slate-800'}">
                    ${isExcl ? `<svg viewBox="0 0 12 12" width="10" height="10"><line x1="2" y1="2" x2="10" y2="10" stroke="#94a3b8" stroke-width="1.5"/><line x1="10" y1="2" x2="2" y2="10" stroke="#94a3b8" stroke-width="1.5"/></svg>` : ''}
                </button>`
                : `<span class="w-5 h-5 shrink-0"></span>`}
            </div>`;
        }

        // Board slots GMS has not released yet. One line for the lot of them —
        // drawing an empty row each would push the inputs off-screen for the sake
        // of slots you cannot fill.
        const pending = Math.max(0, slots - skills.length);
        if (pending > 0) {
            rows += `<div class="flex items-center gap-2 pt-1.5">
                <div class="flex gap-1 shrink-0">
                    ${Array.from({ length: pending }, () => '<span class="w-2.5 h-2.5 rounded-sm border border-dashed border-slate-700"></span>').join('')}
                </div>
                <div class="flex-1 text-[10px] text-slate-600 tracking-widest uppercase">未実装 ×${pending}</div>
            </div>`;
        }

        return `<div class="bg-slate-900 rounded-xl border border-slate-800 px-2.5 py-1.5">
            <div class="text-[10px] font-bold uppercase tracking-wider mb-1" style="color:${tier.color}">${tier.label}</div>
            <div>${rows}</div>
        </div>`;
    },

    // Level pickers are dropdowns rather than number fields: every change
    // re-renders the panel, which would throw the caret out of a text field
    // after the first digit. `from` is the lowest level offered — the node's
    // floor for the current level, the current level for the target.
    levelOptions(from, selected) {
        let html = '';
        for (let v = from; v <= this.MAX_LEVEL; v++) {
            html += `<option value="${v}"${v === selected ? ' selected' : ''}>${v}</option>`;
        }
        return html;
    },

    // Sort key and upper bound for the plan. Shared by every 強化順マップ view, so
    // flipping either one keeps all views describing the same chain.
    buildPlanControls() {
        const seg = (active, onclick, label, hint) => `<button onclick="${onclick}" title="${hint}"
            class="px-2.5 py-1 text-[11px] font-bold transition-colors ${active ? 'bg-violet-600 text-white' : 'text-slate-400 hover:text-slate-200'}">${label}</button>`;
        const group = (title, buttons) => `<div class="flex items-center gap-2">
            <span class="text-[10px] text-slate-500">${title}</span>
            <div class="inline-flex border border-slate-700 bg-slate-950 divide-x divide-slate-700">${buttons}</div>
        </div>`;
        const view = this.modalTab === 'map' ? group('表示',
            seg(this.mapView === 'list', "hexaTracker.setMapView('list')", '効率順', '次に上げるものを1行ずつ並べる')
            + seg(this.mapView === 'tiles', "hexaTracker.setMapView('tiles')", 'マス', '同じ順番を左上から右へアイコンで並べる')
            + seg(this.mapView === 'timeline', "hexaTracker.setMapView('timeline')", 'タイムライン', 'ノードごとの行に、上げる時期を横に並べる')) : '';
        return `<div class="flex flex-wrap items-center gap-x-5 gap-y-2 border border-slate-800 bg-slate-900 px-2.5 py-2 mb-2">
            ${view}
            ${group('並べ替え',
                seg(this.prioritySort === 'frag', "hexaTracker.setPrioritySort('frag')", 'フラグメント効率', '最終ダメージ / ソルエルダフラグメント で並べ替え')
                + seg(this.prioritySort === 'erda', "hexaTracker.setPrioritySort('erda')", 'エルダ効率', '最終ダメージ / ソルエルダ で並べ替え'))}
            ${group('上限',
                seg(this.planCap === 'target', "hexaTracker.setPlanCap('target')", '目標値まで', '進捗入力で決めた目標値で止める')
                + seg(this.planCap === 'max', "hexaTracker.setPlanCap('max')", '最大 Lv.30 まで', '目標値を無視して全ノードLv.30まで並べる'))}
        </div>`;
    },

    // Ranked "what to level next", by Final Damage gained per Sol Erda Fragment
    // (or per Sol Erda). Runs from the entered current levels up to the targets.
    buildPriority(classId, trackingId) {
        const cls = this.getClassSkills(classId);
        const info = this.getClassInfo(classId);
        if (!cls || !info) return this.buildEmptyState();

        const steps = this.buildPlan(trackingId, classId);
        const now = this.getProgress(trackingId, classId);
        const perErda = this.prioritySort === 'erda';

        const header = this.buildPlanControls();

        if (!steps.length) {
            return `<div>${header}
                <div class="flex items-center justify-center h-40 text-center text-slate-500">
                    <div><i data-lucide="check-circle-2" class="w-10 h-10 mx-auto mb-3 opacity-30"></i>
                    <p class="text-sm">${this.planCap === 'max' ? '全ノードLv.30に到達済みです' : '目標値に到達済みです'}</p>
                    <p class="text-xs mt-1">
                        最終ダメージ <span class="font-bold text-emerald-300">+${now.fdNow.toFixed(1)}%</span>
                        ${now.fdMax - now.fdNow > 0.05
                            ? ` — 全取得まで残り <span class="font-bold text-amber-300">+${(now.fdMax - now.fdNow).toFixed(1)}%</span>`
                            : '（全取得済み）'}
                    </p>
                    ${this.planCap === 'max' ? '' : '<p class="text-xs mt-1 opacity-70">進捗入力タブで目標値を上げるか、上限を「最大 Lv.30」に切り替えると、ここに次の一手が並びます。</p>'}</div>
                </div></div>`;
        }

        let cumFrag = 0, cumErda = 0, cumFd = 0;
        let rows = '';
        steps.forEach((step, i) => {
            cumFrag += step.frag; cumErda += step.erda; cumFd += step.fd;
            const s = step.skill;
            const sCfg = this.SKILL_TYPE_CONFIG[s.type] || this.SKILL_TYPE_CONFIG.mastery;
            const iconUrl = this.getSkillIcon(s);
            const iconHtml = iconUrl
                ? `<img src="${iconUrl}" class="w-8 h-8 object-contain shrink-0 rounded" loading="lazy" alt="">`
                : `<div class="w-8 h-8 rounded-full flex items-center justify-center text-[11px] font-bold text-white shrink-0" style="background:${sCfg.badge}">${sCfg.label}</div>`;

            const levels = step.to - step.from;

            rows += `<div class="flex items-center gap-3 py-2 px-2.5 rounded-lg ${i % 2 ? 'bg-slate-900/40' : ''}">
                <span class="w-6 text-right text-[11px] font-bold text-slate-500 tabular-nums shrink-0">${i + 1}</span>
                ${iconHtml}
                <div class="flex-1 min-w-0">
                    <div class="flex items-baseline gap-2">
                        <span class="text-xs text-slate-200 truncate" title="${this.escHtml(s.name)}">${this.escHtml(s.name)}</span>
                        <span class="text-[9px] font-bold uppercase tracking-wider shrink-0" style="color:${sCfg.color}">${sCfg.title}</span>
                    </div>
                    <div class="text-[10px] text-slate-500 tabular-nums">
                        Lv.${step.from} → ${step.to}${levels > 1 ? `（${levels}段階）` : ''}
                        · <span class="text-violet-300">${step.frag.toLocaleString()}</span> フラグメント
                        · <span class="text-amber-300">${step.erda.toLocaleString()}</span> エルダ
                        · ここまで計 <span class="text-slate-400">${cumFrag.toLocaleString()}</span> フラグメント
                    </div>
                </div>
                <div class="text-right shrink-0">
                    <div class="text-sm font-bold text-emerald-300 tabular-nums">+${step.fd.toFixed(2)}%</div>
                    <div class="text-[9px] text-slate-500 tabular-nums" title="${perErda ? 'エルダ1あたりの最終ダメージ' : 'フラグメント100あたりの最終ダメージ'}">
                        ${perErda ? (step.erda > 0 ? (step.fd / step.erda).toFixed(3) : '—') + ' /エルダ'
                                  : (step.frag > 0 ? (step.fd / step.frag * 100).toFixed(3) : '—') + ' /100frag'}
                    </div>
                </div>
            </div>`;
        });

        return `<div>
            ${header}
            <div class="flex flex-wrap items-center gap-x-4 gap-y-1 text-[11px] text-slate-400 mb-2 px-1">
                <span>全${steps.length}ステップ</span>
                <span class="text-violet-300">フラグメント計 <span class="font-bold tabular-nums">${cumFrag.toLocaleString()}</span></span>
                <span class="text-amber-300">エルダ計 <span class="font-bold tabular-nums">${cumErda.toLocaleString()}</span></span>
                <span class="text-emerald-300" title="この計画をやりきったときに増える最終ダメージ。実ダメージでは +${this.damageGain(now.fdNow, now.fdNow + cumFd).toFixed(1)}% です。">
                    最終ダメージ <span class="font-bold tabular-nums">+${now.fdNow.toFixed(1)}%</span>
                    <span class="text-slate-500">→</span>
                    <span class="font-bold tabular-nums">+${(now.fdNow + cumFd).toFixed(1)}%</span>
                    <span class="text-slate-500">(+${cumFd.toFixed(1)})</span>
                </span>
            </div>
            <div class="bg-slate-900/40 border border-slate-800 rounded-xl p-2 divide-y divide-slate-800/40">${rows}</div>
            <p class="text-[10px] text-slate-600 mt-3 leading-relaxed">
                現在地から${this.planCap === 'max' ? '全ノードLv.30' : '目標値'}まで、1レベルずつ「最終ダメージ / 消費リソース」が最大の一手を選び続けた順序です。
                同じスキルの連続レベルは1ステップにまとめています。リソース消費量は正確な値、最終ダメージ量はノード係数からの推定値です。
            </p>
        </div>`;
    },

    // ========== Plan map: the whole 効率順 chain at a glance ==========

    // The same steps as 効率順, drawn as a wall of icon tiles read left to right,
    // like the build-order images people pass around. The tile that crosses each
    // 10% of the class's maximum Final Damage is flagged, so you can see where
    // the chain slows down.
    buildPlanMap(classId, trackingId) {
        if (this.mapView === 'list') return this.buildPriority(classId, trackingId);
        const cls = this.getClassSkills(classId);
        const info = this.getClassInfo(classId);
        if (!cls || !info) return this.buildEmptyState();

        const steps = this.buildPlan(trackingId, classId);
        const now = this.getProgress(trackingId, classId);
        const header = this.buildPlanControls();
        if (!steps.length) {
            return `<div>${header}
                <div class="flex items-center justify-center h-40 text-sm text-slate-500">
                    ${this.planCap === 'max' ? '全ノードLv.30に到達済みです' : '目標値に到達済みです（上限を「最大 Lv.30」にすると続きが出ます）'}
                </div></div>`;
        }
        if (this.mapView === 'timeline') return this.buildPlanTimeline(classId, trackingId, steps, now);

        const fdMax = now.fdMax;
        const pctOf = fd => fdMax > 0 ? fd / fdMax * 100 : 0;
        let nextMark = Math.floor(pctOf(now.fdNow) / 10) * 10 + 10;
        let cumFrag = 0, cumErda = 0, fd = now.fdNow;
        let tiles = '';
        steps.forEach((step, i) => {
            cumFrag += step.frag; cumErda += step.erda; fd += step.fd;
            const s = step.skill;
            const sCfg = this.SKILL_TYPE_CONFIG[s.type] || this.SKILL_TYPE_CONFIG.mastery;
            const iconUrl = this.getSkillIcon(s);
            const icon = iconUrl
                ? `<img src="${iconUrl}" class="w-8 h-8 object-contain" loading="lazy" alt="">`
                : `<div class="w-8 h-8 flex items-center justify-center text-[11px] font-bold text-white" style="background:${sCfg.badge}">${sCfg.label}</div>`;
            const hint = `${i + 1}. ${s.name}\nLv.${step.from} → ${step.to}\nフラグメント ${step.frag.toLocaleString()}（計 ${cumFrag.toLocaleString()}）\nエルダ ${step.erda.toLocaleString()}\n最終ダメージ +${step.fd.toFixed(2)}%（計 +${fd.toFixed(1)}%）`;
            // Mark the tile that carries you past each 10% of max Final Damage.
            let crossed = null;
            while (nextMark <= 100 && pctOf(fd) >= nextMark - 1e-9) { crossed = nextMark; nextMark += 10; }
            tiles += `<div class="relative flex flex-col items-center pt-3 pb-1 bg-slate-900 border border-slate-800 ${crossed !== null ? 'ring-1 ring-inset ring-emerald-500/60' : ''}" style="border-top:2px solid ${sCfg.badge}" title="${this.escHtml(hint)}">
                <span class="absolute top-0.5 left-1 text-[9px] text-slate-500 tabular-nums">${i + 1}</span>
                ${crossed !== null ? `<span class="absolute top-0.5 right-1 text-[9px] font-bold text-emerald-300 tabular-nums">${crossed}%</span>` : ''}
                ${icon}
                <span class="mt-1 text-[10px] tabular-nums text-slate-500 leading-none">${step.from}→<span class="text-[12px] font-bold text-slate-100">${step.to}</span></span>
            </div>`;
        });

        return `<div>
            ${header}
            ${this.buildPlanSummary(steps.length, cumFrag, cumErda, now.fdNow, fd)}
            <div class="grid gap-1" style="grid-template-columns:repeat(auto-fill,minmax(58px,1fr))">${tiles}</div>
            <p class="text-[10px] text-slate-600 mt-3 leading-relaxed">
                効率順と同じ順番を、左上から右へ並べたものです。数字は「今のLv→上げた後のLv」。マスにマウスを乗せると消費量が出ます。
                緑の枠と%は、そのマスで全取得時の最終ダメージの何%に届くかの目印です。
            </p>
        </div>`;
    },

    // One line of totals over every 強化順マップ view, with the node-type legend.
    buildPlanSummary(count, frag, erda, fdFrom, fdTo) {
        const legend = ['origin', 'ascent', 'mastery', 'enhance', 'common'].map(t => {
            const c = this.SKILL_TYPE_CONFIG[t];
            return `<span class="inline-flex items-center gap-1"><span class="inline-block w-2.5 h-0.5" style="background:${c.badge}"></span>${c.title}</span>`;
        }).join('');
        return `<div class="flex flex-wrap items-center gap-x-4 gap-y-1 text-[11px] text-slate-400 mb-2 px-1">
            <span>全${count}ステップ</span>
            <span class="text-violet-300">フラグメント計 <span class="font-bold tabular-nums">${frag.toLocaleString()}</span></span>
            <span class="text-amber-300">エルダ計 <span class="font-bold tabular-nums">${erda.toLocaleString()}</span></span>
            <span class="text-emerald-300">最終ダメージ <span class="font-bold tabular-nums">+${fdFrom.toFixed(1)}%</span> <span class="text-slate-500">→</span> <span class="font-bold tabular-nums">+${fdTo.toFixed(1)}%</span></span>
            <span class="ml-auto flex items-center gap-3 text-[10px] text-slate-500">${legend}</span>
        </div>`;
    },

    // Board order for the timeline rows: Skill Node, Mastery, Boost, Common.
    boardOrder(skills) {
        const tierIdx = t => { const i = this.TIERS.findIndex(x => x.id === t); return i < 0 ? 99 : i; };
        return [...skills].sort((a, b) => tierIdx(a.tier) - tierIdx(b.tier) || (a.slot || 0) - (b.slot || 0));
    },

    // ----- Timeline: one row per node, x = total levels taken -----

    // The plan unrolled into single levels, with running totals at every
    // position, so dragging the line only has to look numbers up.
    buildTimelineData(classId, trackingId, steps, now) {
        const skills = this.boardOrder(this.damageSkills(trackingId, classId));
        const byKey = {};
        const current = {}, final = {};
        for (const s of skills) {
            byKey[s.key] = s;
            current[s.key] = final[s.key] = this.levelOf(trackingId, s);
        }
        const singles = [];
        const frag = [0], erda = [0], fd = [0];
        const segs = [];
        for (const st of steps) {
            const s = st.skill;
            segs.push({ key: s.key, start: singles.length, from: st.from, to: st.to });
            for (let lv = st.from + 1; lv <= st.to; lv++) {
                singles.push({ key: s.key, lv });
                const k = singles.length;
                frag[k] = frag[k - 1] + this.fragAt(s, lv) - this.fragAt(s, lv - 1);
                erda[k] = erda[k - 1] + this.erdaAt(s, lv) - this.erdaAt(s, lv - 1);
                fd[k] = fd[k - 1] + this.fdAt(s, lv) - this.fdAt(s, lv - 1);
            }
            final[s.key] = st.to;
        }
        // Where the line crosses each 10% of the class's maximum Final Damage.
        const marks = [];
        const pctOf = v => now.fdMax > 0 ? v / now.fdMax * 100 : 0;
        let next = Math.floor(pctOf(now.fdNow) / 10) * 10 + 10;
        for (let k = 1; k <= singles.length; k++) {
            while (next <= 100 && pctOf(now.fdNow + fd[k]) >= next - 1e-9) { marks.push({ k, pct: next }); next += 10; }
        }
        // The x axis is fragments spent: axis[k] is the running total after k levels.
        const axis = frag;
        return { skills, byKey, current, final, singles, segs, frag, erda, fd, marks, now, total: singles.length, axis, axisMax: axis[singles.length] || 0 };
    },

    buildPlanTimeline(classId, trackingId, steps, now) {
        const tl = this.buildTimelineData(classId, trackingId, steps, now);
        this._tl = tl;
        const L = tl.total;
        this.mapCursor = Math.max(0, Math.min(L, this.mapCursor | 0));
        const pos = k => tl.axisMax > 0 ? tl.axis[k] / tl.axisMax : 0;
        const x = k => (pos(k) * 100).toFixed(3) + '%';
        const LABEL_W = 236;

        // Lines for every mark, but a label only where it has room.
        let lastLabel = -1;
        const seekMarks = tl.marks.filter(m => { if (pos(m.k) - lastLabel < 0.035) return false; lastLabel = pos(m.k); return true; }).map(m => `<button onclick="hexaTracker.setMapCursor(${m.k})" title="全取得時FDの${m.pct}%に届く位置へ"
            class="absolute top-0 ${pos(m.k) > 0.97 ? '-translate-x-full' : pos(m.k) < 0.03 ? '' : '-translate-x-1/2'} text-[9px] font-bold text-emerald-300 tabular-nums hover:text-emerald-100" style="left:${x(m.k)}">${m.pct}%</button>`).join('');
        const markLines = tl.marks.map(m => `<div class="absolute top-0 bottom-0 border-l border-dashed border-emerald-500/40 pointer-events-none" style="left:${x(m.k)}"></div>`).join('');

        const rows = tl.skills.map(s => {
            const c = this.SKILL_TYPE_CONFIG[s.type] || this.SKILL_TYPE_CONFIG.mastery;
            const segs = tl.segs.filter(g => g.key === s.key).map(g => {
                const n = g.to - g.from;
                const w = (pos(g.start + n) - pos(g.start)) * 100;
                return `<div data-tl-seg="${g.start}" data-tl-end="${g.start + n}" class="absolute top-[4px] bottom-[4px] border flex items-center justify-center overflow-hidden"
                    title="${this.escHtml(s.name)}\nLv.${g.from} → ${g.to}（${g.start + 1}〜${g.start + n}レベル目）"
                    style="left:${x(g.start)};width:${w.toFixed(3)}%;border-color:${c.badge}">
                    ${w > 2.2 ? `<span class="text-[9px] font-bold tabular-nums" style="color:${c.color}">${g.to}</span>` : ''}</div>`;
            }).join('');
            return `<div class="flex items-stretch border-t border-slate-800 h-7">
                <div class="shrink-0 flex items-center gap-1.5 px-1.5 border-r border-slate-800" style="width:${LABEL_W}px;box-shadow:inset 2px 0 0 ${c.badge}">
                    ${this.mapIcon(s, 20)}
                    <span class="text-[11px] text-slate-300 truncate flex-1" title="${this.escHtml(s.name)}">${this.escHtml(s.name)}</span>
                    <span id="tl-lv-${s.key}" class="font-mono text-[10px] text-slate-500 whitespace-pre shrink-0"></span>
                </div>
                <div class="relative flex-1">${segs}</div>
            </div>`;
        }).join('');

        // Ticks at even steps of fragments, labelled as the running total
        // including what is already spent.
        const tickLabel = v => (now.fragSpent + Math.round(v)).toLocaleString();
        let ticks = '';
        for (let q = 0; q <= 4; q++) {
            ticks += `<span class="absolute text-[9px] text-slate-500 tabular-nums ${q === 0 ? '' : q === 4 ? '-translate-x-full' : '-translate-x-1/2'}" style="left:${q * 25}%">${tickLabel(tl.axisMax * q / 4)}</span>`;
        }

        const total = { frag: tl.frag[L], erda: tl.erda[L], fd: now.fdNow + tl.fd[L] };
        const html = `<div>
            ${this.buildPlanControls()}
            ${this.buildPlanSummary(steps.length, total.frag, total.erda, now.fdNow, total.fd)}
            <div class="border border-slate-800 bg-slate-900 select-none">
                <div class="flex border-b border-slate-800">
                    <div class="shrink-0 border-r border-slate-800 px-1.5 flex items-center justify-between text-[9px] text-slate-500" style="width:${LABEL_W}px">
                        <span>ノード</span><span class="font-mono whitespace-pre">線の位置 / 最終</span>
                    </div>
                    <div class="relative flex-1 h-9 mx-0">
                        <div class="absolute inset-x-0 top-0 h-3">${seekMarks}</div>
                        <div id="tl-seek" class="absolute inset-x-0 bottom-1 h-4 cursor-pointer" tabindex="0"
                            onpointerdown="hexaTracker.tlPointer(event)" onpointermove="hexaTracker.tlPointer(event)" onkeydown="hexaTracker.tlKey(event)">
                            <div class="absolute inset-x-0 top-1/2 h-px bg-slate-700"></div>
                            <div id="tl-seek-fill" class="absolute left-0 top-1/2 -mt-px h-[3px] bg-violet-500"></div>
                            <div id="tl-seek-knob" class="absolute top-0 bottom-0 w-2.5 -ml-[5px] bg-slate-100 border border-violet-500"></div>
                        </div>
                    </div>
                </div>
                <div class="relative">
                    <div class="absolute inset-y-0 right-0 pointer-events-none" style="left:${LABEL_W}px">
                        ${markLines}
                        <div id="tl-line" class="absolute top-0 bottom-0 w-px bg-violet-400"></div>
                    </div>
                    <div class="cursor-col-resize" onpointerdown="hexaTracker.tlPointer(event)" onpointermove="hexaTracker.tlPointer(event)">${rows}</div>
                </div>
                <div class="flex h-5 border-t border-slate-800">
                    <div class="shrink-0 border-r border-slate-800 px-1.5 text-[9px] text-slate-500 flex items-center" style="width:${LABEL_W}px">フラグメント（投入済み含む）</div>
                    <div class="relative flex-1 pt-1">${ticks}</div>
                </div>
            </div>
            <div id="tl-readout" class="mt-2"></div>
            <p class="text-[10px] text-slate-600 mt-3 leading-relaxed">
                効率順と同じ順番を、ノードごとの行に分けて並べました。横軸は使ったフラグメントで、帯の幅がその一手の消費量です。帯の数字は上げた後のLvです。
                上のバーか図の上をドラッグすると線が動き、その時点の各ノードのLv（白は今から上がるもの）と、そこまでの消費量・最終ダメージが下に出ます。緑の%を押すと、全取得時FDのその割合に届く位置へ線が飛びます。
            </p>
        </div>`;
        // Fill in the line-dependent parts once the markup is in the page.
        setTimeout(() => this.tlUpdate(), 0);
        return html;
    },

    mapIcon(s, size) {
        const c = this.SKILL_TYPE_CONFIG[s.type] || this.SKILL_TYPE_CONFIG.mastery;
        const url = this.getSkillIcon(s);
        return url
            ? `<img src="${url}" class="object-contain shrink-0" style="width:${size}px;height:${size}px" loading="lazy" alt="">`
            : `<div class="flex items-center justify-center text-[10px] font-bold text-white shrink-0" style="width:${size}px;height:${size}px;background:${c.badge}">${c.label}</div>`;
    },

    // Drag on the seek bar or anywhere over the rows. Only the line-dependent
    // bits are rewritten, so the drag is never interrupted by a re-render.
    tlPointer(ev) {
        if (ev.type === 'pointermove' && !(ev.buttons & 1)) return;
        const tl = this._tl;
        if (!tl || !tl.total) return;
        if (ev.type === 'pointerdown') ev.currentTarget.setPointerCapture(ev.pointerId);
        const plot = document.getElementById('tl-seek');
        if (!plot) return;
        const r = plot.getBoundingClientRect();
        // A press on the node names is not a seek.
        if (ev.type === 'pointerdown' && ev.clientX < r.left - 4) return;
        const target = Math.max(0, Math.min(1, (ev.clientX - r.left) / r.width)) * tl.axisMax;
        // axis is non-decreasing: find the first k at or past the pointer, then
        // take whichever neighbour is closer.
        let lo = 0, hi = tl.total;
        while (lo < hi) { const mid = (lo + hi) >> 1; if (tl.axis[mid] < target) lo = mid + 1; else hi = mid; }
        const k = lo > 0 && target - tl.axis[lo - 1] < tl.axis[lo] - target ? lo - 1 : lo;
        this.setMapCursor(k);
    },

    tlKey(ev) {
        const step = ev.shiftKey ? 10 : 1;
        if (ev.key === 'ArrowLeft') this.setMapCursor(this.mapCursor - step);
        else if (ev.key === 'ArrowRight') this.setMapCursor(this.mapCursor + step);
        else return;
        ev.preventDefault();
    },

    setMapCursor(k) {
        const tl = this._tl;
        if (!tl) return;
        this.mapCursor = Math.max(0, Math.min(tl.total, k));
        this.tlUpdate();
    },

    // Levels of every node after the first k levels of the plan.
    tlLevelsAt(k) {
        const tl = this._tl;
        const lv = { ...tl.current };
        for (let i = 0; i < k; i++) lv[tl.singles[i].key] = tl.singles[i].lv;
        return lv;
    },

    tlUpdate() {
        const tl = this._tl;
        if (!tl || !document.getElementById('tl-line')) return;
        const k = this.mapCursor;
        const pos = ((tl.axisMax > 0 ? tl.axis[k] / tl.axisMax : 0) * 100).toFixed(3) + '%';
        document.getElementById('tl-line').style.left = pos;
        document.getElementById('tl-seek-knob').style.left = pos;
        document.getElementById('tl-seek-fill').style.width = pos;

        const lv = this.tlLevelsAt(k);
        const pad = n => String(n).padStart(2, ' ');
        for (const s of tl.skills) {
            const el = document.getElementById('tl-lv-' + s.key);
            if (!el) continue;
            const moved = lv[s.key] !== tl.current[s.key];
            el.innerHTML = `<b class="${moved ? 'text-slate-100' : 'text-slate-500'}">${pad(lv[s.key])}</b><span class="text-slate-600">/${pad(tl.final[s.key])}</span>`;
        }
        // Segments already taken at the line read solid; the rest stay faint.
        document.querySelectorAll('[data-tl-seg]').forEach(el => {
            const start = +el.dataset.tlSeg, end = +el.dataset.tlEnd;
            el.style.opacity = start >= k ? '0.45' : '1';
            el.style.background = end <= k ? 'rgba(148,163,184,0.10)' : 'transparent';
            el.style.borderStyle = start < k && end > k ? 'dashed' : 'solid';
        });

        const now = tl.now;
        const frag = tl.frag[k], erda = tl.erda[k], fd = now.fdNow + tl.fd[k];
        const fragAll = now.fragSpent + frag, erdaAll = now.erdaSpent + erda;
        const pct = now.fragMax > 0 ? fragAll / now.fragMax * 100 : 0;
        const fdPct = now.fdMax > 0 ? fd / now.fdMax * 100 : 0;
        // Every node's level at the line, in board order, then the totals.
        const nodes = tl.skills.map(s => {
            const c = this.SKILL_TYPE_CONFIG[s.type] || this.SKILL_TYPE_CONFIG.mastery;
            const moved = lv[s.key] !== tl.current[s.key];
            return `<div class="flex items-center gap-1.5 px-1.5 py-1 border-b border-r border-slate-800" style="box-shadow:inset 0 2px 0 ${c.badge}" title="${this.escHtml(s.name)}">
                ${this.mapIcon(s, 22)}
                <div class="min-w-0 flex-1">
                    <div class="text-[10px] text-slate-400 truncate leading-tight">${this.escHtml(s.name)}</div>
                    <div class="font-mono whitespace-pre text-[10px] text-slate-500 leading-tight"><span class="text-slate-600">Lv.</span><b class="text-[13px] ${moved ? 'text-slate-100' : 'text-slate-500'}">${pad(lv[s.key])}</b></div>
                </div>
            </div>`;
        }).join('');
        const stat = (label, value, sub, color) => `<span class="whitespace-nowrap">${label} <b class="tabular-nums" style="color:${color}">${value}</b>${sub ? ` <span class="text-slate-600 tabular-nums">${sub}</span>` : ''}</span>`;
        document.getElementById('tl-readout').innerHTML = `<div class="border border-slate-800 bg-slate-900">
            <div class="grid border-l border-slate-800 -ml-px" style="grid-template-columns:repeat(auto-fill,minmax(150px,1fr))">${nodes}</div>
            <div class="flex flex-wrap gap-x-4 gap-y-0.5 px-2 py-1 text-[10px] text-slate-500">
                ${stat('フラグメント', fragAll.toLocaleString(), `(+${frag.toLocaleString()} / ${now.fragMax.toLocaleString()})`, '#c4b5fd')}
                ${stat('ソルエルダ', erdaAll.toLocaleString(), `(+${erda.toLocaleString()} / ${now.erdaMax.toLocaleString()})`, '#fcd34d')}
                ${stat('最終ダメージ', `+${fd.toFixed(1)}%`, `(全取得時の ${fdPct.toFixed(1)}%)`, '#6ee7b7')}
                ${stat('進捗', `${pct.toFixed(1)}%`, '(フラグメント換算)', '#a5b4fc')}
            </div>
        </div>`;
    },


    // ========== Efficiency curve tab ==========

    // Chart geometry, in viewBox units. Kept on the object so the hover handler
    // can invert a mouse position back to a point without re-deriving it.
    CHART: { W: 760, H: 290, padL: 54, padR: 14, padT: 12, padB: 42 },
    // Validated against the slate-900 card surface: lightness band, chroma floor,
    // CVD separation (worst adjacent ΔE 9.7) and 3:1 contrast all pass.
    CHART_INK: { curve: '#0ea570', breakEven: '#d97706', you: '#7c5cf0', surface: '#0f172a' },

    buildCurveTab(classId, trackingId) {
        const cls = this.getClassSkills(classId);
        const info = this.getClassInfo(classId);
        if (!cls || !info) return this.buildEmptyState();

        const curve = this.curveData(trackingId, classId);
        if (curve.totalFrag <= 0) {
            return `<div class="flex items-center justify-center h-40 text-center text-slate-500">
                <div><i data-lucide="activity" class="w-10 h-10 mx-auto mb-3 opacity-30"></i>
                <p class="text-sm">この職業はまだ効率を計算できるノードがありません</p></div>
            </div>`;
        }

        const now = this.getProgress(trackingId, classId);
        const brk = curve.points[curve.breakIdx];
        const per1k = r => (r * 1000).toFixed(1);

        // Marginal rate just past the break-even point, for the contrast.
        const after = curve.points[Math.min(curve.breakIdx + 1, curve.points.length - 1)];
        const brkPct = curve.fdMax > 0 ? brk.fd / curve.fdMax * 100 : 0;
        const brkFragPct = curve.totalFrag > 0 ? brk.frag / curve.totalFrag * 100 : 0;

        const tile = (label, value, sub, color, hint) => `<div class="flex-1 min-w-[150px] px-3 py-2" title="${this.escHtml(hint)}">
            <div class="text-[10px] uppercase tracking-wider text-slate-500">${label}</div>
            <div class="text-lg font-bold tabular-nums leading-tight" style="color:${color}">${value}</div>
            <div class="text-[10px] text-slate-500 leading-tight mt-0.5">${sub}</div>
        </div>`;

        const summary = `<div class="bg-slate-900 rounded-xl border border-slate-800 p-3 mb-3">
            <div class="flex flex-wrap items-stretch divide-x divide-slate-800">
                ${tile('全体の平均効率', per1k(curve.avg), '欠片1,000あたりのFD', '#94a3b8',
                    '未強化の盤面を全ノードLv.30まで持っていったときの、欠片あたり最終ダメージの平均。下のグラフの破線の傾きです。')}
                ${tile('コスパの分岐点', `FD ${brkPct.toFixed(0)}%`, `欠片 ${brk.frag.toLocaleString()}（全体の ${brkFragPct.toFixed(0)}%）`, this.CHART_INK.breakEven,
                    '1レベルあたりの効率が全体平均と並ぶ地点。ここまでは平均より割がよく、ここから先は平均を下回ります。')}
                ${tile('分岐点までの効率', per1k(curve.avg > 0 && brk.frag > 0 ? (brk.fd - curve.fdFloor) / brk.frag : 0), `ここから先は ${per1k(after.ratio)}`, '#34d399',
                    '分岐点までの平均効率と、その直後の1レベルの効率。落ち込み幅がそのまま「伸ばしにくさ」です。')}
                ${tile('あなたの現在地', `FD ${now.fdMax > 0 ? (now.fdNow / now.fdMax * 100).toFixed(0) : 0}%`, `欠片 ${now.fragSpent.toLocaleString()} 投入済み`, this.CHART_INK.you,
                    'いまの最終ダメージが、全取得時に対して何%かです。')}
            </div>
        </div>`;

        return `<div>
            ${summary}
            ${this.buildCurveChart(curve, now)}
            ${this.buildCurveTable(curve, now, per1k)}
            <p class="text-[10px] text-slate-600 mt-2 leading-relaxed">
                未強化の盤面から全ノードLv.30までを、「最終ダメージ / 欠片」が最大の順に振ったときの積み上げです。
                Lv.10/20/30はコストが跳ね上がるため、壁をまたぐ複数レベルをひとまとめに評価しています。
                現在地や目標値には影響されないので、職業ごとの伸び方の目安として使えます。
                消費リソースは正確な値、最終ダメージはノード係数からの推定値です。${this.exclusionSentence(classId)}
            </p>
        </div>`;
    },

    buildCurveChart(curve, now) {
        const { W, H, padL, padR, padT, padB } = this.CHART;
        const ink = this.CHART_INK;
        const plotW = W - padL - padR, plotH = H - padT - padB;
        const x = frag => padL + (curve.totalFrag > 0 ? frag / curve.totalFrag : 0) * plotW;
        const y = fd => padT + (1 - (curve.fdMax > 0 ? fd / curve.fdMax : 0)) * plotH;

        // Keep the geometry around for the hover handler.
        this._curve = { ...curve, W, H, padL, plotW, plotH };

        const line = curve.points.map(p => `${x(p.frag).toFixed(1)},${y(p.fd).toFixed(1)}`).join(' ');
        const area = `${padL},${padT + plotH} ${line} ${x(curve.totalFrag).toFixed(1)},${padT + plotH}`;

        let grid = '';
        for (let k = 0; k <= 5; k++) {
            const fd = curve.fdMax * k / 5;
            const gy = y(fd);
            grid += `<line x1="${padL}" y1="${gy.toFixed(1)}" x2="${padL + plotW}" y2="${gy.toFixed(1)}" stroke="#1e293b" stroke-width="1"/>
                <text x="${padL - 8}" y="${(gy + 3.5).toFixed(1)}" text-anchor="end" fill="#64748b" font-size="10">${k * 20}%</text>`;
        }
        let ticks = '';
        for (let k = 0; k <= 4; k++) {
            const frag = curve.totalFrag * k / 4;
            const tx = x(frag);
            ticks += `<text x="${tx.toFixed(1)}" y="${(padT + plotH + 16).toFixed(1)}" text-anchor="middle" fill="#64748b" font-size="10">${Math.round(frag / 1000)}k</text>`;
        }

        const brk = curve.points[curve.breakIdx];
        const bx = x(brk.frag), by = y(brk.fd);
        const labelLeft = bx > padL + plotW * 0.62;

        // Your own position sits wherever your fragments actually went, which is
        // not necessarily on the optimal curve.
        const showYou = now.fragSpent > 0;
        const yx = x(Math.min(now.fragSpent, curve.totalFrag)), yy = y(Math.min(now.fdNow, curve.fdMax));

        return `<div class="bg-slate-900 rounded-xl border border-slate-800 p-3 mb-3 relative">
            <div class="flex flex-wrap items-center justify-between gap-2 mb-1 px-1">
                <div class="flex items-center gap-1.5 text-[10px] font-bold uppercase tracking-wider text-emerald-300">
                    <i data-lucide="activity" class="w-3.5 h-3.5"></i>欠片の投入量と最終ダメージ
                </div>
                <div class="flex items-center gap-3 text-[10px] text-slate-400">
                    <span class="flex items-center gap-1"><span class="inline-block w-3 h-0.5" style="background:${ink.curve}"></span>最適順で振った場合</span>
                    <span class="flex items-center gap-1"><span class="inline-block w-3 border-t border-dashed border-slate-500"></span>全体平均の傾き</span>
                </div>
            </div>
            <svg viewBox="0 0 ${W} ${H}" class="w-full" style="height:auto" role="img"
                aria-label="欠片の累計投入量に対する最終ダメージの伸びを示す曲線。下の早見表に同じ数値があります。">
                <defs><linearGradient id="hexaCurveFill" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="0%" stop-color="${ink.curve}" stop-opacity="0.28"/>
                    <stop offset="100%" stop-color="${ink.curve}" stop-opacity="0.02"/>
                </linearGradient></defs>
                ${grid}${ticks}
                <line x1="${padL}" y1="${padT}" x2="${padL}" y2="${padT + plotH}" stroke="#334155" stroke-width="1"/>
                <line x1="${padL}" y1="${padT + plotH}" x2="${padL + plotW}" y2="${padT + plotH}" stroke="#334155" stroke-width="1"/>
                <polygon points="${area}" fill="url(#hexaCurveFill)"/>
                <line x1="${x(0)}" y1="${y(curve.fdFloor).toFixed(1)}" x2="${x(curve.totalFrag)}" y2="${y(curve.fdMax).toFixed(1)}"
                    stroke="#64748b" stroke-width="1.5" stroke-dasharray="5 4"/>
                <polyline points="${line}" fill="none" stroke="${ink.curve}" stroke-width="2" stroke-linejoin="round"/>

                <line id="hexa-curve-cross" x1="0" y1="${padT}" x2="0" y2="${padT + plotH}" stroke="#94a3b8" stroke-width="1" stroke-dasharray="3 3" style="display:none"/>
                <circle id="hexa-curve-dot" r="4.5" fill="#e2e8f0" stroke="${ink.surface}" stroke-width="2" style="display:none"/>

                <line x1="${bx.toFixed(1)}" y1="${by.toFixed(1)}" x2="${bx.toFixed(1)}" y2="${padT + plotH}" stroke="${ink.breakEven}" stroke-width="1" stroke-dasharray="3 3" opacity="0.7"/>
                <circle cx="${bx.toFixed(1)}" cy="${by.toFixed(1)}" r="5" fill="${ink.breakEven}" stroke="${ink.surface}" stroke-width="2"/>
                <text x="${(labelLeft ? bx - 10 : bx + 10).toFixed(1)}" y="${(by - 10).toFixed(1)}" text-anchor="${labelLeft ? 'end' : 'start'}" fill="#fbbf24" font-size="11" font-weight="bold">分岐点</text>
                <text x="${(labelLeft ? bx - 10 : bx + 10).toFixed(1)}" y="${(by + 2).toFixed(1)}" text-anchor="${labelLeft ? 'end' : 'start'}" fill="#94a3b8" font-size="10">欠片 ${brk.frag.toLocaleString()} / FD +${brk.fd.toFixed(1)}%</text>
                ${showYou ? `<circle cx="${yx.toFixed(1)}" cy="${yy.toFixed(1)}" r="5" fill="${ink.you}" stroke="${ink.surface}" stroke-width="2"/>
                <text x="${(yx + 9).toFixed(1)}" y="${(yy + 14).toFixed(1)}" fill="#c4b5fd" font-size="11" font-weight="bold">現在地</text>` : ''}

                <rect x="${padL}" y="${padT}" width="${plotW}" height="${plotH}" fill="transparent"
                    onmousemove="hexaTracker.curveHover(event)" onmouseleave="hexaTracker.curveHover(null)"/>
            </svg>
            <div id="hexa-curve-tip" class="absolute z-10 pointer-events-none hidden rounded-lg border border-slate-700 bg-slate-950/95 px-2.5 py-1.5 text-[10px] leading-relaxed shadow-xl"></div>
            <div class="flex items-center justify-between text-[10px] text-slate-600 mt-1 px-1">
                <span>縦軸: 全取得時を100%とした最終ダメージ</span>
                <span>横軸: ソルエルダフラグメントの累計投入量</span>
            </div>
        </div>`;
    },

    // Crosshair + readout. Bound inline so it survives the innerHTML re-render.
    curveHover(ev) {
        const tip = document.getElementById('hexa-curve-tip');
        const cross = document.getElementById('hexa-curve-cross');
        const dot = document.getElementById('hexa-curve-dot');
        const c = this._curve;
        if (!tip || !cross || !dot) return;
        if (!ev || !c) {
            tip.classList.add('hidden');
            cross.style.display = 'none';
            dot.style.display = 'none';
            return;
        }
        const svg = ev.currentTarget.ownerSVGElement;
        const box = svg.getBoundingClientRect();
        if (!box.width) return;
        const vx = (ev.clientX - box.left) / box.width * c.W;
        const frag = Math.max(0, Math.min(c.totalFrag, (vx - c.padL) / c.plotW * c.totalFrag));

        let best = c.points[0];
        for (const p of c.points) { if (Math.abs(p.frag - frag) < Math.abs(best.frag - frag)) best = p; }

        const px = c.padL + (best.frag / c.totalFrag) * c.plotW;
        const py = this.CHART.padT + (1 - best.fd / c.fdMax) * c.plotH;
        cross.setAttribute('x1', px); cross.setAttribute('x2', px);
        cross.style.display = '';
        dot.setAttribute('cx', px); dot.setAttribute('cy', py);
        dot.style.display = '';

        const pct = c.fdMax > 0 ? best.fd / c.fdMax * 100 : 0;
        const rate = Number.isFinite(best.ratio) ? (best.ratio * 1000).toFixed(1) : '—';
        tip.innerHTML = `<div class="font-bold text-slate-100">FD +${best.fd.toFixed(1)}% <span class="text-slate-500 font-normal">(${pct.toFixed(0)}%)</span></div>
            <div class="text-violet-300 tabular-nums">欠片 ${Math.round(best.frag).toLocaleString()}</div>
            <div class="text-amber-300 tabular-nums">エルダ ${Math.round(best.erda).toLocaleString()}</div>
            <div class="text-slate-400 tabular-nums">この地点の効率 ${rate} / 欠片1,000</div>
            ${best.skill ? `<div class="text-slate-500 mt-0.5">直前: ${this.escHtml(best.skill.name)} Lv.${best.to}</div>` : ''}`;
        tip.classList.remove('hidden');

        // Keep the card inside the chart box.
        const leftPx = px / c.W * box.width;
        const flip = leftPx > box.width * 0.55;
        tip.style.left = flip ? '' : (leftPx + 16) + 'px';
        tip.style.right = flip ? (box.width - leftPx + 16) + 'px' : '';
        tip.style.top = '44px';
    },

    // The same curve as a table: what each 20% of Final Damage costs.
    buildCurveTable(curve, now, per1k) {
        const brk = curve.points[curve.breakIdx];
        const rows = [];
        for (let k = 1; k <= 5; k++) {
            const fdWanted = curve.fdMax * k / 5;
            const { p } = this.curveAt(curve, fdWanted);
            rows.push({ label: `${k * 20}%`, p, mark: false });
        }
        rows.push({ label: '分岐点', p: brk, mark: true });
        rows.sort((a, b) => a.p.fd - b.p.fd || (a.mark ? -1 : 1));

        const nowPct = curve.fdMax > 0 ? now.fdNow / curve.fdMax * 100 : 0;
        let body = '';
        for (const r of rows) {
            const reached = now.fdNow >= r.p.fd - 1e-9;
            body += `<tr class="${r.mark ? 'bg-amber-500/10' : ''} ${reached ? 'text-slate-500' : 'text-slate-300'}">
                <td class="py-1 px-2 whitespace-nowrap">
                    ${r.mark ? `<span class="inline-block w-1.5 h-1.5 rounded-full mr-1.5 align-middle" style="background:${this.CHART_INK.breakEven}"></span>` : ''}
                    <span class="${r.mark ? 'font-bold text-amber-300' : 'font-bold'}">${r.label}</span>
                    ${reached ? '<span class="text-[9px] text-emerald-500 ml-1">到達済</span>' : ''}
                </td>
                <td class="py-1 px-2 text-right tabular-nums text-emerald-300">+${r.p.fd.toFixed(1)}%</td>
                <td class="py-1 px-2 text-right tabular-nums text-violet-300">${Math.round(r.p.frag).toLocaleString()}</td>
                <td class="py-1 px-2 text-right tabular-nums text-amber-300">${Math.round(r.p.erda).toLocaleString()}</td>
                <td class="py-1 px-2 text-right tabular-nums">${Number.isFinite(r.p.ratio) ? per1k(r.p.ratio) : '—'}</td>
            </tr>`;
        }

        return `<div class="bg-slate-900 rounded-xl border border-slate-800 p-3">
            <div class="flex flex-wrap items-center justify-between gap-2 mb-2 px-1">
                <div class="flex items-center gap-1.5 text-[10px] font-bold uppercase tracking-wider text-slate-300">
                    <i data-lucide="table" class="w-3.5 h-3.5"></i>FD進捗ごとの必要量（早見表）
                </div>
                <span class="text-[10px] text-slate-500">現在 ${nowPct.toFixed(0)}%</span>
            </div>
            <div class="overflow-x-auto">
                <table class="w-full text-[11px] border-collapse">
                    <thead><tr class="text-[9px] uppercase tracking-wider text-slate-500 border-b border-slate-800">
                        <th class="py-1 px-2 text-left font-bold">FD進捗</th>
                        <th class="py-1 px-2 text-right font-bold">最終ダメージ</th>
                        <th class="py-1 px-2 text-right font-bold" title="累計のソルエルダフラグメント">必要欠片</th>
                        <th class="py-1 px-2 text-right font-bold" title="累計のソルエルダ">必要エルダ</th>
                        <th class="py-1 px-2 text-right font-bold" title="その地点で1レベル上げたときの、欠片1,000あたりの最終ダメージ">その地点の効率</th>
                    </tr></thead>
                    <tbody class="divide-y divide-slate-800/60">${body}</tbody>
                </table>
            </div>
        </div>`;
    },

    // Re-render every live HEXA surface: the page behind the modal (so a card's
    // progress updates as you type) and the modal itself.
    refreshAll() {
        const page = document.getElementById('hexa-page');
        if (page && this.page === 'tracker') page.innerHTML = this.buildPageBody();
        const mtabs = document.getElementById('hexa-modal-tabs');
        if (mtabs && this.modalClassId) mtabs.innerHTML = this.buildTabs();
        const mcontent = document.getElementById('hexa-modal-content');
        if (mcontent && this.modalClassId) mcontent.innerHTML = this.buildModalContent();
        const mhead = document.getElementById('hexa-modal-progress');
        if (mhead && this.modalTrackingId) mhead.innerHTML = this.buildModalHeaderStat();
        if (window.lucide) lucide.createIcons();
    },

    ensureEntry(trackingId) {
        if (!this.data[trackingId]) this.data[trackingId] = { levels: {}, targets: {}, excluded: {} };
        const e = this.data[trackingId];
        if (!e.levels) e.levels = {};
        if (!e.targets) e.targets = {};
        if (!e.excluded) e.excluded = {};
        return e;
    },

    findSkill(classId, skillKey) {
        const cls = this.getClassSkills(classId);
        return cls ? cls.skills.find(s => s.key === skillKey) : null;
    },

    updateLevel(trackingId, classId, skillKey, value) {
        const skill = this.findSkill(classId, skillKey);
        if (!skill) return;
        const e = this.ensureEntry(trackingId);
        const lvl = this.clampLevel(skill, value);
        e.levels[skillKey] = lvl;
        // A target below the current level is meaningless; pull it up with you.
        if (typeof e.targets[skillKey] === 'number' && e.targets[skillKey] < lvl) e.targets[skillKey] = lvl;
        this.saveData();
        this.refreshAll();
    },

    updateTarget(trackingId, classId, skillKey, value) {
        const skill = this.findSkill(classId, skillKey);
        if (!skill) return;
        const e = this.ensureEntry(trackingId);
        const cur = Math.max(this.minLevel(skill), e.levels[skillKey] || 0);
        e.targets[skillKey] = Math.max(cur, this.clampLevel(skill, value));
        this.saveData();
        this.refreshAll();
    },

    toggleExclude(trackingId, skillKey) {
        const e = this.ensureEntry(trackingId);
        e.excluded[skillKey] = !e.excluded[skillKey];
        this.saveData();
        this.refreshAll();
    },

    // ========== Character-linked modal ==========
    modalCharId: null,
    modalClassId: null,
    modalTrackingId: null,
    modalTab: 'progress',   // 'progress' | 'map' | 'curve'

    // Resolve a dashboard character's job name to a HEXA classId (or null if no HEXA data).
    resolveClassId(jobName) {
        if (!jobName || typeof window === 'undefined' || !window.CLASS_DATA) return null;
        const norm = s => String(s).toLowerCase().replace(/[^a-z0-9]/g, '');
        const target = norm(jobName);
        for (const arr of Object.values(window.CLASS_DATA)) {
            const m = arr.find(j => norm(j.name) === target || norm(j.id) === target);
            if (m && this.getClassSkills(m.id)) return m.id;
        }
        return null;
    },

    // Resolve the HEXA classId for a character: manual assignment first, then auto-match by job name.
    getCharClassId(char) {
        if (!char) return null;
        this.ensureLoaded();
        const saved = this.data['char:' + char.id];
        if (saved && saved.classId && this.getClassSkills(saved.classId)) return saved.classId;
        return this.resolveClassId(char.job);
    },

    openForCharacter(charId) {
        this.ensureLoaded();
        const char = (window.app && window.app.data && window.app.data.characters || []).find(c => c.id === charId);
        if (!char) return;
        const classId = this.getCharClassId(char);
        if (!classId) {
            // No HEXA class linked yet — let the user register one.
            this.openClassPicker(charId);
            return;
        }
        this.modalCharId = charId;
        this.modalClassId = classId;
        this.modalTrackingId = 'char:' + charId;
        this.renderModal(char);
    },

    // Shared overlay element + Escape handler for any HEXA modal/picker.
    ensureOverlay() {
        let overlay = document.getElementById('hexa-modal-overlay');
        if (!overlay) {
            overlay = document.createElement('div');
            overlay.id = 'hexa-modal-overlay';
            document.body.appendChild(overlay);
        }
        overlay.className = 'fixed inset-0 z-[200] flex items-center justify-center bg-black/70 backdrop-blur-sm p-3';
        overlay.setAttribute('onclick', 'if(event.target===this)hexaTracker.closeModal()');
        if (!this._escHandler) {
            this._escHandler = (e) => { if (e.key === 'Escape') this.closeModal(); };
            document.addEventListener('keydown', this._escHandler);
        }
        return overlay;
    },

    // Class registration picker for characters whose job can't be auto-matched (or to re-assign).
    openClassPicker(charId) {
        this.ensureLoaded();
        const char = (window.app && window.app.data && window.app.data.characters || []).find(c => c.id === charId);
        if (!char) return;
        const guess = this.resolveClassId(char.job);
        const current = this.getCharClassId(char);
        let groupsHtml = '';
        if (window.CLASS_DATA) {
            for (const [groupId, classes] of Object.entries(CLASS_DATA)) {
                const hexaClasses = classes.filter(c => this.getClassSkills(c.id));
                if (!hexaClasses.length) continue;
                const label = this.GROUP_LABELS[groupId] || groupId;
                let cards = '';
                for (const cls of hexaClasses) {
                    const sel = (cls.id === current);
                    cards += `<button onclick="hexaTracker.assignClass('${charId}','${cls.id}')"
                        title="${this.escHtml(cls.name)}"
                        class="flex flex-col items-center gap-1 p-2 rounded-lg border transition-colors ${sel ? 'bg-violet-700/40 border-violet-400 ring-1 ring-violet-400' : 'bg-slate-800/60 border-slate-700 hover:bg-violet-700/30 hover:border-violet-500'}">
                        <img src="${cls.path}" class="w-9 h-9 object-contain" loading="lazy">
                        <span class="text-[9px] text-slate-300 text-center leading-tight">${this.escHtml(cls.name)}</span>
                    </button>`;
                }
                groupsHtml += `<div class="mb-3">
                    <div class="text-[9px] text-slate-500 font-bold uppercase tracking-widest mb-1.5">${this.escHtml(label)}</div>
                    <div class="grid grid-cols-5 sm:grid-cols-6 gap-1.5">${cards}</div>
                </div>`;
            }
        }
        const overlay = this.ensureOverlay();
        overlay.innerHTML = `
            <div class="bg-slate-950 border border-slate-700 shadow-2xl w-full max-w-2xl max-h-[85vh] flex flex-col overflow-hidden">
                <div class="flex items-stretch justify-between shrink-0 bg-slate-900 border-b border-slate-800" style="box-shadow:inset 0 -1px 0 rgba(99,102,241,0.25)">
                    <div class="min-w-0 px-3 py-2">
                        <div class="text-white font-bold text-[15px] truncate">${this.escHtml(char.name)} — HEXA職業を登録</div>
                        <div class="text-[11px] text-slate-400 mt-0.5">進捗を管理する職業を選択してください${char.job ? `（現在の職業: ${this.escHtml(char.job)}${guess ? '' : ' — 自動判定できませんでした'}）` : ''}</div>
                    </div>
                    <button onclick="hexaTracker.closeModal()" title="閉じる" class="shrink-0 w-11 border-l border-slate-800 text-slate-400 hover:text-white hover:bg-slate-800 flex items-center justify-center transition-colors"><i data-lucide="x" class="w-4 h-4"></i></button>
                </div>
                <div class="overflow-y-auto custom-scrollbar p-4 flex-1">${groupsHtml || '<p class="text-slate-500 text-sm text-center py-8">職業データがありません</p>'}</div>
            </div>`;
        if (window.lucide) lucide.createIcons();
    },

    // Save a manual class assignment for a character, then open its progress modal.
    assignClass(charId, classId) {
        const tid = 'char:' + charId;
        this.ensureEntry(tid).classId = classId;
        this.saveData();
        this.openForCharacter(charId);
        this.refreshRoster();
    },

    buildModalHeaderStat() {
        const p = this.getProgress(this.modalTrackingId, this.modalClassId);
        return `<span title="いま出ている最終ダメージ / 全取得時">FD <span class="text-[15px] font-bold text-emerald-300">+${p.fdNow.toFixed(1)}%</span><span class="text-slate-600"> / +${p.fdMax.toFixed(1)}%</span></span>
            <span title="投入済みフラグメント / 全取得に必要なフラグメント">欠片 <span class="text-[15px] font-bold text-violet-300">${p.fragSpent.toLocaleString()}</span><span class="text-slate-600"> / ${p.fragMax.toLocaleString()}</span></span>
            <span class="text-[15px] font-bold text-slate-200 w-11 text-right">${p.pct}%</span>`;
    },

    buildModalContent() {
        if (this.modalTab === 'map') return this.buildPlanMap(this.modalClassId, this.modalTrackingId);
        if (this.modalTab === 'curve') return this.buildCurveTab(this.modalClassId, this.modalTrackingId);
        return this.buildSkillPanel(this.modalClassId, this.modalTrackingId);
    },

    renderModal(char) {
        const info = this.getClassInfo(this.modalClassId) || {};
        const portrait = (char.image && char.image.startsWith('http')) ? char.image : (char.classImage || info.path || '');
        this.renderModalShell({
            portrait,
            portraitClass: 'w-8 h-8 object-cover bg-slate-950',
            title: this.escHtml(char.name),
            badge: char.level ? `<span class="text-[11px] font-mono text-slate-400">Lv.${this.escHtml(char.level)}</span>` : '',
            actions: `<button onclick="hexaTracker.openClassPicker('${this.modalCharId}')" title="HEXA職業を変更" class="w-11 border-l border-slate-800 text-slate-400 hover:text-white hover:bg-slate-800 flex items-center justify-center transition-colors">
                <i data-lucide="repeat" class="w-4 h-4"></i>
            </button>`,
        });
    },

    // Open the tracker for a class on its own, with no character attached.
    // Levels saved here live under the class id, the same as before.
    openForClass(classId) {
        this.ensureLoaded();
        if (!this.getClassSkills(classId)) return;
        const info = this.getClassInfo(classId);
        this.modalCharId = null;
        this.modalClassId = classId;
        this.modalTrackingId = classId;
        this.renderModalShell({
            portrait: info ? info.path : '',
            portraitClass: 'w-8 h-8 object-contain',
            title: this.escHtml(info ? info.name : classId),
            badge: `<span class="text-[11px] text-slate-500">${this.escHtml(this.getClassGroup(classId))}</span>`,
            actions: '',
        });
    },

    renderModalShell({ portrait, portraitClass, title, badge, actions }) {
        const overlay = this.ensureOverlay();
        // One header row, laid out like the site's own top bar: who, then the
        // tabs, then the running totals, then close.
        overlay.innerHTML = `
            <div class="bg-slate-950 border border-slate-700 shadow-2xl w-full max-w-5xl h-[720px] max-h-[94vh] flex flex-col overflow-hidden">
                <div class="flex items-stretch h-11 shrink-0 bg-slate-900 border-b border-slate-800" style="box-shadow:inset 0 -1px 0 rgba(99,102,241,0.25)">
                    <div class="flex items-center gap-2 pl-2 pr-3 min-w-0 max-w-[260px] border-r border-slate-800">
                        ${portrait ? `<img src="${portrait}" class="${portraitClass} shrink-0">` : ''}
                        <span class="text-[15px] font-bold text-white truncate">${title}</span>
                        ${badge}
                    </div>
                    <nav id="hexa-modal-tabs" class="flex self-stretch px-1">${this.buildTabs()}</nav>
                    <div id="hexa-modal-progress" class="ml-auto flex items-center gap-4 px-3 text-[11px] text-slate-400 font-mono tabular-nums whitespace-nowrap">${this.buildModalHeaderStat()}</div>
                    ${actions}
                    <button onclick="hexaTracker.closeModal()" title="閉じる" class="w-11 border-l border-slate-800 text-slate-400 hover:text-white hover:bg-slate-800 flex items-center justify-center transition-colors">
                        <i data-lucide="x" class="w-4 h-4"></i>
                    </button>
                </div>
                <div id="hexa-modal-content" class="overflow-y-auto custom-scrollbar px-4 py-3 flex-1">
                    ${this.buildModalContent()}
                </div>
            </div>`;
        if (window.lucide) lucide.createIcons();
    },

    closeModal() {
        const overlay = document.getElementById('hexa-modal-overlay');
        if (overlay) overlay.remove();
        if (this._escHandler) { document.removeEventListener('keydown', this._escHandler); this._escHandler = null; }
        this.modalCharId = null;
        this.modalClassId = null;
        this.modalTrackingId = null;
        const page = document.getElementById('hexa-page');
        if (page && this.page === 'tracker') {
            page.innerHTML = this.buildPageBody();
            if (window.lucide) lucide.createIcons();
        }
        this.refreshRoster();
    },

    // Refresh both the roster cards and the dashboard so HEXA badges reflect the latest progress.
    refreshRoster() {
        if (!window.app) return;
        if (typeof window.app.renderCharacters === 'function') window.app.renderCharacters();
        if (typeof window.app.renderDashboard === 'function') window.app.renderDashboard();
    },

    escHtml(s) {
        return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
    },
};
